import json


def normalize_expense(expense):
    normalized_expense = {
        'vendor': expense.get('vendor'),
        'date': expense.get('date'),
        'total': expense.get('total'),
        'items': []
    }
    for item in expense.get('line_items', []) or expense.get('items', []):
        normalized_item = {
            'description': item.get('description'),
            'quantity': item.get('quantity'),
            'amount': item.get('amount')
        }
        normalized_expense['items'].append(normalized_item)
    return json.dumps(normalized_expense, indent=2)

import json


def validate_document_fields(document):
    required_fields = ['vendor', 'date', 'total', 'items']
    errors = []
    for field in required_fields:
        if field not in document:
            errors.append(f'Missing required field: {field}')
        elif field == 'items' and not isinstance(document[field], list):
            errors.append(f'Invalid type for field: {field}')
    if errors:
        return json.dumps({'errors': errors}, indent=2)
    return json.dumps({'status': 'valid'}, indent=2)

import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def get_document_client():
    return DocumentIntelligenceClient(os.getenv('DOCUMENT_INTELLIGENCE_ENDPOINT'), AzureKeyCredential(os.getenv('DOCUMENT_INTELLIGENCE_API_KEY')))

from typing import Dict, Any


def normalize_document_request(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'document_bytes': payload['document_bytes'],
        'mime_type': payload['mime_type']
    }


def normalize_document_response(response: Dict[str, Any]) -> Dict[str, Any]:
    documents = []
    for document in response.get('documents', []):
        fields = document.get('fields', {})
        normalized_fields = {key: value['content'] for key, value in fields.items()}
        documents.append(normalized_fields)
    return {'documents': documents}

import json


def summarize_invoice_fields(invoice):
    summary = {
        'vendor': invoice.get('vendor'),
        'date': invoice.get('date'),
        'total': invoice.get('total'),
        'item_count': len(invoice.get('line_items', []))
    }
    return json.dumps(summary, indent=2)
